#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "seidel-2d.h"

/* Include the Exo-generated kernel header. */
#include "generated/seidel-2d/seidel-2d.h"


/* Array initialization. */
static
void init_array (int n,
                 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
                 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# In-place Gauss–Seidel (Seidel-2D) relaxation on an n x n grid.
@proc
def kernel_seidel_2d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # Need at least a 3x3 grid to apply the 3x3 stencil.
    assert n > 2

    # Precompute 1/9 once to avoid repeated divisions in the inner loops.
    inv9: DATA_TYPE
    inv9 = 1.0 / 9.0

    for t in seq(0, tsteps):
        # Sweep in lexicographic (i,j) order as in the PolyBench reference.
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                # Accumulate the 3x3 neighborhood into a scalar, then scale.
                s: DATA_TYPE
                s = (
                    A[i - 1, j - 1] + A[i - 1, j] + A[i - 1, j + 1]
                    + A[i,     j - 1] + A[i,     j] + A[i,     j + 1]
                    + A[i + 1, j - 1] + A[i + 1, j] + A[i + 1, j + 1]
                )
                A[i, j] = s * inv9


# ------------------------
# Scheduling / optimization
# ------------------------

# Start from the base kernel.
seidel_opt = kernel_seidel_2d

# Tile and unroll the innermost j loop to expose a fixed-size inner kernel.
TILE_J = 4  # tuning knob; small to keep register pressure reasonable

# Find the original j loop inside the (t, i, j) nest.
j_loop = seidel_opt.find_loop("j")

# Strip-mine the j loop: j -> (jo, ji) with inner extent TILE_J.
# This preserves the original lexicographic (i,j) order, which is
# essential for correctness of the in-place Gauss–Seidel update.
seidel_opt = divide_loop(seidel_opt, j_loop, TILE_J, ("jo", "ji"), tail="guard")

# Unroll the fixed-size inner ji loop to improve ILP and aid auto-vectorization.
ji_loop = seidel_opt.find_loop("ji")
seidel_opt = unroll_loop(seidel_opt, ji_loop)

# Clean up any algebraic artifacts introduced by the transformations.
seidel_opt = simplify(seidel_opt)

# Expose the optimized procedure under the original name so the generated
# C function is still called `kernel_seidel_2d` from this driver.
kernel_seidel_2d = seidel_opt
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D view to 1D pointer. */
  kernel_seidel_2d(/*ctxt=*/NULL, tsteps, n,
                   (DATA_TYPE*)POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
